import Foundation
import XCTest
@testable import HomeostatCore

/// The Swift engine must reproduce the Python pipeline for every synthetic
/// dataset checkpoint (engine_parity.json, regenerated by
/// backend/tests/engine/test_parity_fixture.py).
final class EngineParityTests: XCTestCase {
    let data = fixtures.deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .deletingLastPathComponent().deletingLastPathComponent().appendingPathComponent("data/synthetic")

    func json(_ url: URL) throws -> JSONValue { try JSONDecoder().decode(JSONValue.self, from: Data(contentsOf: url)) }

    func testEveryCheckpointMatchesThePythonEngine() throws {
        guard case .array(let expected) = try json(fixtures.appendingPathComponent("engine_parity.json")) else {
            return XCTFail("fixture is not a list")
        }
        var datasets: [String: (observations: [EngineObservation], context: JSONValue)] = [:]
        var mismatches: [String] = []
        for entry in expected {
            let name = entry["dataset"]!.string!, checkpoint = entry["checkpoint"]!.string!
            if datasets[name] == nil { datasets[name] = try load(data.appendingPathComponent(name)) }
            let (observations, context) = datasets[name]!
            let engineContext = try makeContext(context, checkpoint)
            let features = try calculateFeatures(observations, engineContext)
            let state = computeHealthState(features)
            let widget = try JSONDecoder().decode(JSONValue.self, from: JSONEncoder().encode(mapWidgetState(state)))
            for (part, actual) in [("features", features.json), ("health_state", state.json), ("widget_state", widget),
                                   ("diagnostics", .array(features.diagnostics.map(JSONValue.string)))] {
                mismatches += differences(entry[part]!, actual, "\(name)@\(checkpoint).\(part)")
            }
        }
        XCTAssertEqual(expected.count, 170)
        XCTAssertTrue(mismatches.isEmpty, "\(mismatches.count) mismatches:\n" + mismatches.prefix(40).joined(separator: "\n"))
    }

    func testTheBackendHashesTheSameSettings() throws {
        let settings = try JSONDecoder().decode(JSONValue.self, from: Data(EngineSettings.canonicalJSON.utf8))
        let s = EngineSettings.standard
        XCTAssertEqual(settings["baseline"]?["window_days"], .int(Int64(s.windowDays)))
        XCTAssertEqual(settings["baseline"]?["minimum_valid_days"], .int(Int64(s.minimumValidDays)))
        XCTAssertEqual(settings["movement"]?["behind_ratio"], .double(s.behindRatio))
        XCTAssertEqual(settings["movement"]?["ahead_ratio"], .double(s.aheadRatio))
        XCTAssertEqual(settings["sleep"]?["overnight_start"], .string("\(s.overnightStartHour):00:00"))
        XCTAssertEqual(settings["sleep"]?["overnight_end"], .string("\(s.overnightEndHour):00:00"))
        guard case .array(let groups)? = settings["source_groups"] else { return XCTFail() }
        XCTAssertEqual(groups.map { $0["id"]?.string }, s.sourceGroups.map(\.id))
    }

    func load(_ directory: URL) throws -> ([EngineObservation], JSONValue) {
        let lines = try String(contentsOf: directory.appendingPathComponent("events.jsonl"), encoding: .utf8)
            .split(separator: "\n")
        var events: [String: EngineEvent] = [:]
        for line in lines {
            let event = try EngineEvent(json: JSONDecoder().decode(JSONValue.self, from: Data(line.utf8)))
            events[event.eventID] = event
        }
        guard case .array(let deliveries) = try json(directory.appendingPathComponent("deliveries.json")) else {
            throw EngineEvent.ParseError.invalid("deliveries")
        }
        var observations: [EngineObservation] = []
        for delivery in deliveries {
            guard case .array(let ids)? = delivery["event_ids"] else { continue }
            let at = Instant.parse(delivery["delivered_at"]!.string!)!
            observations += ids.map { EngineObservation(event: events[$0.string!.lowercased()]!, deliveredAt: at) }
        }
        return (observations, try json(directory.appendingPathComponent("context.json")))
    }

    func makeContext(_ context: JSONValue, _ checkpoint: String) throws -> EngineContext {
        let zone = context["timezone"]!.string!
        guard case .array(let points)? = context["checkpoints"], case .array(let windows)? = context["coverage"],
              let point = points.first(where: { $0["id"]?.string == checkpoint }) else { throw EngineEvent.ParseError.invalid("context") }
        let effective = Instant.parse(point["effective_at"]!.string!)!
        let coverage = windows.flatMap { window in
            Domain.allCases.map { domain in
                EngineCoverage(domain: domain, timezone: zone, complete: window["domains"]?[domain.rawValue]?.string != "unavailable",
                               startDay: LocalDay(window["start_day"]!.string!), endDay: LocalDay(window["end_day"]!.string!))
            }
        }
        return EngineContext(day: Zone(zone)!.day(of: effective), timezone: zone, effectiveAt: effective,
                             knownAt: Instant.parse(point["known_at"]!.string!)!, coverage: coverage)
    }
}

/// Field-by-field differences; numbers match within 1e-9, and a missing key equals null.
func differences(_ expected: JSONValue, _ actual: JSONValue, _ path: String) -> [String] {
    func number(_ value: JSONValue) -> Double? {
        switch value {
        case .int(let n): Double(n)
        case .double(let d): d
        default: nil
        }
    }
    switch (expected, actual) {
    case (.object(let a), .object(let b)):
        return Set(a.keys).union(b.keys).sorted().flatMap { key in
            differences(a[key] ?? .null, b[key] ?? .null, "\(path).\(key)")
        }
    case (.array(let a), .array(let b)):
        guard a.count == b.count else { return ["\(path): \(a.count) items, got \(b.count)"] }
        return zip(a, b).enumerated().flatMap { differences($1.0, $1.1, "\(path)[\($0)]") }
    default:
        if let x = number(expected), let y = number(actual) {
            return abs(x - y) <= 1e-9 * max(1, abs(x)) ? [] : ["\(path): \(x), got \(y)"]
        }
        return expected == actual ? [] : ["\(path): \(expected), got \(actual)"]
    }
}
